        completionTokens,
        totalTokens,
        cost,
        lastReqTokens: pt + ct,
        lastReqMs: latencyMs,
      };
      try {
        localStorage.setItem("senpai_neural_usage_v9", JSON.stringify(next));
      } catch (_) {}
