import React, { useRef, useEffect } from "react";
import { AttachedFile } from "../types";
import { Mic, Paperclip, X, Send, StopCircle, Image as ImageIcon, FileText } from "lucide-react";

interface InputAreaProps {
  input: string;
  onInputChange: (val: string) => void;
  onSend: () => void;
  onCancel: () => void;
  isStreaming: boolean;
  isRecording: boolean;
  onToggleRecord: () => void;
  attachedFiles: AttachedFile[];
  onAddFiles: (files: FileList) => void;
  onRemoveFile: (index: number) => void;
}

export const InputArea: React.FC<InputAreaProps> = ({
  input,
  onInputChange,
  onSend,
  onCancel,
  isStreaming,
  isRecording,
  onToggleRecord,
  attachedFiles,
  onAddFiles,
  onRemoveFile,
}) => {
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Auto resize textarea
  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = "auto";
      textareaRef.current.style.height = `${Math.min(textareaRef.current.scrollHeight, 120)}px`;
    }
  }, [input]);

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      if ((input.trim() || attachedFiles.length > 0) && !isStreaming) {
        onSend();
      }
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      onAddFiles(e.target.files);
      e.target.value = ""; // reset input
    }
  };

  return (
    <div className="flex flex-col p-3 sm:p-4 border-t border-white/10 bg-slate-950/60 backdrop-blur-xl shrink-0 select-none">
      {/* Attached Files Previews */}
      {attachedFiles.length > 0 && (
        <div className="flex flex-wrap gap-2 mb-3 px-1">
          {attachedFiles.map((file, idx) => {
            const isImg = file.mimeType.startsWith("image/");
            return (
              <div
                key={idx}
                className="relative flex items-center gap-2 bg-slate-900/90 border border-white/10 rounded-xl p-1.5 pr-3 max-w-[190px] shadow-sm font-mono text-[11px] text-slate-200 backdrop-blur-md"
              >
                {isImg ? (
                  <div className="w-8 h-8 rounded-lg overflow-hidden bg-black shrink-0 border border-white/10">
                    <img src={`data:${file.mimeType};base64,${file.base64Data}`} alt={file.name} className="w-full h-full object-cover" />
                  </div>
                ) : (
                  <div className="w-8 h-8 rounded-lg bg-white/5 border border-white/10 flex items-center justify-center shrink-0 text-cyan-400">
                    <FileText className="w-4 h-4" />
                  </div>
                )}
                <div className="truncate flex-1">
                  <div className="truncate font-semibold text-[10px] font-mono">{file.name}</div>
                  <div className="text-[8px] text-cyan-400 font-mono tracking-widest uppercase">{isImg ? "IMAGE" : "TEXT/DATA"}</div>
                </div>
                <button
                  onClick={() => onRemoveFile(idx)}
                  className="absolute -top-1.5 -right-1.5 w-4 h-4 rounded-full bg-rose-500 text-slate-950 flex items-center justify-center text-[10px] font-bold hover:bg-rose-400 transition-colors shadow-[0_0_10px_rgba(244,63,94,0.5)]"
                >
                  ✕
                </button>
              </div>
            );
          })}
        </div>
      )}

      {/* Input Row: Unified sleek grey box containing Mic, Paperclip, Textarea, and Send */}
      <div className="flex items-end gap-1.5 bg-slate-900/90 border border-white/15 rounded-2xl p-1.5 pl-2.5 sm:pl-3 focus-within:border-cyan-400 focus-within:ring-1 focus-within:ring-cyan-400/30 focus-within:bg-slate-900 transition-all duration-200 shadow-xl backdrop-blur-xl">
        {/* Voice Input Button (Inside Input Box) */}
        <button
          onClick={onToggleRecord}
          disabled={isStreaming}
          className={`p-2 rounded-xl transition-all duration-150 shrink-0 ${
            isRecording
              ? "bg-rose-500/20 text-rose-400 animate-pulse shadow-[0_0_12px_rgba(244,63,94,0.5)]"
              : "text-slate-400 hover:text-cyan-400 hover:bg-white/10"
          }`}
          title={isRecording ? "Stop voice recording" : "Start voice recording (Web Speech API)"}
        >
          {isRecording ? <StopCircle className="w-4 h-4" /> : <Mic className="w-4 h-4" />}
        </button>

        {/* File Attachment Button (Inside Input Box) */}
        <button
          onClick={() => fileInputRef.current?.click()}
          disabled={isStreaming}
          className="p-2 rounded-xl text-slate-400 hover:text-cyan-400 hover:bg-white/10 transition-all duration-150 shrink-0"
          title="Attach files or images"
        >
          <Paperclip className="w-4 h-4" />
        </button>
        <input
          ref={fileInputRef}
          type="file"
          multiple
          accept="image/*,.txt,.pdf,.json,.csv,.xml,.md,.py,.js,.html,.css,.log,.sh,.yaml,.yml,.toml"
          onChange={handleFileChange}
          className="hidden"
        />

        {/* Cancel Stream Button */}
        {isStreaming && (
          <button
            onClick={onCancel}
            className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl bg-rose-500/20 border border-rose-500/60 text-rose-300 hover:bg-rose-500/30 font-mono font-bold uppercase tracking-wider text-xs shrink-0 animate-in fade-in"
            title="Cancel request"
          >
            <X className="w-3.5 h-3.5" />
            <span className="hidden sm:inline">Cancel</span>
          </button>
        )}

        {/* Textarea */}
        <div className="flex-1 relative min-w-0 py-0.5">
          <textarea
            ref={textareaRef}
            value={input}
            onChange={(e) => onInputChange(e.target.value)}
            onKeyDown={handleKeyDown}
            rows={1}
            disabled={isStreaming}
            placeholder={isRecording ? "Listening to your voice..." : "Type your message or attach code/data..."}
            className="w-full bg-transparent border-0 px-2 py-1.5 text-slate-200 font-sans text-xs sm:text-sm outline-none resize-none max-h-32 placeholder:text-slate-500 leading-relaxed"
            dir="auto"
          />
        </div>

        {/* Send Button */}
        <button
          onClick={onSend}
          disabled={(!input.trim() && attachedFiles.length === 0) || isStreaming}
          className={`p-2 sm:px-3 sm:py-2 rounded-xl font-bold flex items-center justify-center transition-all duration-150 shrink-0 ${
            (!input.trim() && attachedFiles.length === 0) || isStreaming
              ? "bg-white/5 text-slate-600 cursor-not-allowed"
              : "bg-cyan-400 text-slate-950 hover:bg-cyan-300 shadow-[0_0_15px_rgba(34,211,238,0.5)] hover:scale-105 active:scale-95 font-extrabold"
          }`}
          title="Send message (Enter)"
        >
          <Send className="w-4 h-4 text-slate-950" />
        </button>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from "react";
import { Bitcoin, Coins, TrendingUp, TrendingDown, RefreshCw, Activity } from "lucide-react";

interface CryptoData {
  price: number;
  change24h: number;
}

interface MarketState {
  btc: CryptoData;
  eth: CryptoData;
  lastUpdated: string;
  loading: boolean;
  error?: string;
}

export const MarketTicker: React.FC = () => {
  const [market, setMarket] = useState<MarketState>({
    btc: { price: 97840.50, change24h: 3.42 },
    eth: { price: 2845.20, change24h: 1.85 },
    lastUpdated: new Date().toLocaleTimeString(),
    loading: false,
  });

  const fetchPrices = async () => {
    setMarket((prev) => ({ ...prev, loading: true }));
    try {
      const res = await fetch(
        "https://api.coingecko.com/api/v3/simple/price?ids=bitcoin,ethereum&vs_currencies=usd&include_24hr_change=true"
      );
      if (!res.ok) throw new Error("API rate limit or error");
      const data = await res.json();

      if (data && data.bitcoin && data.ethereum) {
        setMarket({
          btc: {
            price: data.bitcoin.usd || 97840.50,
            change24h: data.bitcoin.usd_24h_change || 0,
          },
          eth: {
            price: data.ethereum.usd || 2845.20,
            change24h: data.ethereum.usd_24h_change || 0,
          },
          lastUpdated: new Date().toLocaleTimeString(),
          loading: false,
        });
      } else {
        setMarket((prev) => ({ ...prev, loading: false }));
      }
    } catch (err) {
      // Keep previous data on network failure or rate limit
      setMarket((prev) => ({
        ...prev,
        loading: false,
        lastUpdated: new Date().toLocaleTimeString(),
      }));
    }
  };

  useEffect(() => {
    fetchPrices();
    const interval = setInterval(fetchPrices, 60000); // Update every 60 seconds
    return () => clearInterval(interval);
  }, []);

  const formatPrice = (val: number) => {
    return new Intl.NumberFormat("en-US", {
      style: "currency",
      currency: "USD",
      minimumFractionDigits: val >= 1000 ? 0 : 2,
      maximumFractionDigits: 2,
    }).format(val);
  };

  const formatChange = (val: number) => {
    const sign = val > 0 ? "+" : "";
    return `${sign}${val.toFixed(2)}%`;
  };

  return (
    <div className="flex items-center gap-2 sm:gap-3.5 bg-slate-950/85 border border-cyan-500/30 px-3 py-1.5 sm:px-4 sm:py-1.5 rounded-full font-mono text-[10px] sm:text-xs text-slate-200 shadow-[0_0_20px_rgba(34,211,238,0.15)] backdrop-blur-xl pointer-events-auto select-none transition-all hover:border-cyan-400/60">
      {/* Live status indicator */}
      <div className="flex items-center gap-1.5 text-cyan-400 font-bold uppercase tracking-wider shrink-0 border-r border-white/10 pr-2 sm:pr-3">
        <span className="w-2 h-2 rounded-full bg-cyan-400 animate-ping shadow-[0_0_8px_#22d3ee]" />
        <span className="hidden lg:inline">MARKET //</span>
      </div>

      {/* Bitcoin Ticker Item */}
      <div className="flex items-center gap-1.5 sm:gap-2">
        <div className="flex items-center justify-center w-4 h-4 sm:w-5 sm:h-5 rounded-full bg-amber-500/20 text-amber-400 border border-amber-500/30 shrink-0">
          <Bitcoin className="w-3 h-3 sm:w-3.5 sm:h-3.5" />
        </div>
        <span className="font-bold text-slate-100">BTC</span>
        <span className="text-amber-300 font-semibold">{formatPrice(market.btc.price)}</span>
        <span
          className={`flex items-center text-[9px] sm:text-[10px] font-bold px-1.5 py-0.5 rounded-md ${
            market.btc.change24h >= 0
              ? "bg-emerald-500/10 text-emerald-400 border border-emerald-500/30"
              : "bg-rose-500/10 text-rose-400 border border-rose-500/30"
          }`}
        >
          {market.btc.change24h >= 0 ? (
            <TrendingUp className="w-2.5 h-2.5 mr-0.5 inline" />
          ) : (
            <TrendingDown className="w-2.5 h-2.5 mr-0.5 inline" />
          )}
          {formatChange(market.btc.change24h)}
        </span>
      </div>

      <span className="text-white/20 hidden sm:inline">|</span>

      {/* Ethereum Ticker Item */}
      <div className="flex items-center gap-1.5 sm:gap-2">
        <div className="flex items-center justify-center w-4 h-4 sm:w-5 sm:h-5 rounded-full bg-indigo-500/20 text-indigo-400 border border-indigo-500/30 shrink-0">
          <Coins className="w-3 h-3 sm:w-3.5 sm:h-3.5" />
        </div>
        <span className="font-bold text-slate-100">ETH</span>
        <span className="text-indigo-300 font-semibold">{formatPrice(market.eth.price)}</span>
        <span
          className={`flex items-center text-[9px] sm:text-[10px] font-bold px-1.5 py-0.5 rounded-md ${
            market.eth.change24h >= 0
              ? "bg-emerald-500/10 text-emerald-400 border border-emerald-500/30"
              : "bg-rose-500/10 text-rose-400 border border-rose-500/30"
          }`}
        >
          {market.eth.change24h >= 0 ? (
            <TrendingUp className="w-2.5 h-2.5 mr-0.5 inline" />
          ) : (
            <TrendingDown className="w-2.5 h-2.5 mr-0.5 inline" />
          )}
          {formatChange(market.eth.change24h)}
        </span>
      </div>

      {/* Refresh action */}
      <button
        onClick={fetchPrices}
        disabled={market.loading}
        title={`Refresh prices (Last updated: ${market.lastUpdated})`}
        className="ml-1 text-slate-400 hover:text-cyan-400 transition-colors p-1 rounded-full hover:bg-white/5 focus:outline-none shrink-0"
      >
        <RefreshCw className={`w-3 h-3 sm:w-3.5 sm:h-3.5 ${market.loading ? "animate-spin text-cyan-400" : ""}`} />
      </button>
    </div>
  );
};

import React, { useState } from "react";
import { Message } from "../types";
import { Copy, Volume2, VolumeX, Pin, RotateCcw, ArrowRight, ThumbsUp, ThumbsDown, Edit3, Trash2, Check, Play, Terminal, Zap } from "lucide-react";

interface MessageItemProps {
  message: Message;
  onCopyText: (text: string) => void;
  onSpeak: (text: string) => void;
  onTogglePin: (id: string) => void;
  onRegenerate: (id: string) => void;
  onContinue: (id: string) => void;
  onFeedback: (id: string, type: "up" | "down") => void;
  onEdit: (id: string, newText: string) => void;
  onDelete: (id: string) => void;
  onRunCode?: (code: string) => void;
  onOpenFrontEnd?: (code: string, lang: string) => void;
  isSpeaking: boolean;
}

export const MessageItem: React.FC<MessageItemProps> = ({
  message,
  onCopyText,
  onSpeak,
  onTogglePin,
  onRegenerate,
  onContinue,
  onFeedback,
  onEdit,
  onDelete,
  onRunCode,
  onOpenFrontEnd,
  isSpeaking,
}) => {
  const [isEditing, setIsEditing] = useState(false);
  const [editText, setEditText] = useState(message.content);
  const [copied, setCopied] = useState(false);
  const [codeCopiedIdx, setCodeCopiedIdx] = useState<number | null>(null);

  const isUser = message.role === "user";

  const handleCopy = () => {
    onCopyText(message.content);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleSaveEdit = () => {
    if (editText.trim() && editText !== message.content) {
      onEdit(message.id, editText.trim());
    }
    setIsEditing(false);
  };

  // Custom Markdown & Code block renderer
  const renderFormattedContent = (content: string) => {
    if (!content) return null;

    // Split by fenced code blocks
    const parts = content.split(/(```[\s\S]*?```)/g);

    return parts.map((part, index) => {
      if (part.startsWith("```") && part.endsWith("```")) {
        const lines = part.slice(3, -3).split("\n");
        const lang = lines[0].trim().toLowerCase() || "code";
        const codeText = (lines[0].trim() ? lines.slice(1) : lines).join("\n");
        const isJs = lang === "js" || lang === "javascript" || lang === "ts" || lang === "typescript";
        const isFrontEnd = lang === "html" || lang === "jsx" || lang === "tsx" || lang === "react" || lang === "css" || lang === "js" || lang === "javascript" || lang === "ts" || lang === "typescript" || lang === "frontend" || lang === "front-end" || lang === "vue" || lang === "svelte" || lang === "ui";

        return (
          <div key={index} className="my-3 rounded-xl overflow-hidden border border-white/10 bg-slate-950/90 shadow-xl font-mono text-[11px] backdrop-blur-md">
            {/* Code header */}
            <div className="flex items-center justify-between px-4 py-2 bg-white/5 border-b border-white/10 text-slate-400 text-[10px]">
              <span className="font-bold uppercase tracking-[0.2em] text-cyan-400 font-mono">{lang}</span>
              <div className="flex items-center gap-1.5 flex-wrap">
                {isFrontEnd && onOpenFrontEnd && (
                  <button
                    onClick={() => onOpenFrontEnd(codeText, lang)}
                    className="flex items-center gap-1 px-2.5 py-0.5 rounded-full bg-gradient-to-r from-cyan-500/20 to-indigo-500/20 border border-cyan-400/80 text-cyan-300 hover:border-cyan-400 hover:bg-cyan-500/30 transition-all font-mono text-[9px] uppercase tracking-wider shadow-[0_0_10px_rgba(34,211,238,0.2)] animate-pulse"
                    title="Open in Front-End Workspace & Live Sandbox"
                  >
                    <Zap className="w-3 h-3 text-cyan-400" />
                    <span>⚡ Live Preview</span>
                  </button>
                )}
                {isJs && onRunCode && (
                  <button
                    onClick={() => onRunCode(codeText)}
                    className="flex items-center gap-1.5 px-2.5 py-0.5 rounded-full bg-emerald-500/20 border border-emerald-500/80 text-emerald-300 hover:bg-emerald-500/30 transition-colors uppercase tracking-wider font-mono text-[9px]"
                    title="Run code block in console"
                  >
                    <Play className="w-3 h-3" />
                    <span>Run JS</span>
                  </button>
                )}
                <button
                  onClick={() => {
                    navigator.clipboard.writeText(codeText);
                    setCodeCopiedIdx(index);
                    setTimeout(() => setCodeCopiedIdx(null), 2000);
                  }}
                  className="flex items-center gap-1.5 px-2.5 py-0.5 rounded-full bg-white/5 border border-white/10 text-slate-300 hover:text-cyan-400 hover:border-cyan-400/50 transition-colors uppercase tracking-wider font-mono text-[9px]"
                >
                  {codeCopiedIdx === index ? <Check className="w-3 h-3 text-emerald-400" /> : <Copy className="w-3 h-3" />}
                  <span>{codeCopiedIdx === index ? "Copied" : "Copy"}</span>
                </button>
              </div>
            </div>
            {/* Code body */}
            <pre className="p-4 overflow-x-auto text-slate-200 leading-relaxed font-mono whitespace-pre text-xs">{codeText}</pre>
          </div>
        );
      }

      // Standard text formatting (bold, headers, lists, inline code)
      const paragraphs = part.split("\n\n");
      return (
        <div key={index} className="space-y-2 leading-relaxed">
          {paragraphs.map((p, pIdx) => {
            const trimmed = p.trim();
            if (!trimmed) return null;

            // Headers
            if (trimmed.startsWith("### ")) {
              return <h4 key={pIdx} className="text-sm font-bold text-cyan-400 mt-2">{trimmed.slice(4)}</h4>;
            }
            if (trimmed.startsWith("## ")) {
              return <h3 key={pIdx} className="text-base font-bold text-cyan-400 mt-3 border-b border-gray-800 pb-1">{trimmed.slice(3)}</h3>;
            }
            if (trimmed.startsWith("# ")) {
              return <h2 key={pIdx} className="text-lg font-black text-white mt-4 border-b border-gray-700 pb-1">{trimmed.slice(2)}</h2>;
            }

            // Blockquote
            if (trimmed.startsWith("> ")) {
              return (
                <blockquote key={pIdx} className="border-l-2 border-purple-500 pl-3 py-0.5 my-1 italic text-gray-400 bg-purple-950/10 rounded-r">
                  {trimmed.slice(2)}
                </blockquote>
              );
            }

            // Bullet list
            if (trimmed.includes("\n- ") || trimmed.startsWith("- ") || trimmed.includes("\n* ") || trimmed.startsWith("* ")) {
              const items = trimmed.split(/\n[-*] /).filter(Boolean);
              return (
                <ul key={pIdx} className="list-disc pl-5 space-y-1 text-gray-300">
                  {items.map((item, iIdx) => (
                    <li key={iIdx}>{item.replace(/^[-*]\s+/, "")}</li>
                  ))}
                </ul>
              );
            }

            // Paragraph with bold/inline code parsing
            const formatInline = (text: string) => {
              const tokens = text.split(/(`.*?`|\*\*.*?\*\*|\*.*?\*)/g);
              return tokens.map((token, tIdx) => {
                if (token.startsWith("`") && token.endsWith("`")) {
                  return <code key={tIdx} className="bg-[#0f1318] border border-gray-800 text-amber-300 px-1.5 py-0.5 rounded text-[11px] font-mono">{token.slice(1, -1)}</code>;
                }
                if (token.startsWith("**") && token.endsWith("**")) {
                  return <strong key={tIdx} className="font-bold text-white">{token.slice(2, -2)}</strong>;
                }
                if (token.startsWith("*") && token.endsWith("*")) {
                  return <em key={tIdx} className="italic text-gray-300">{token.slice(1, -1)}</em>;
                }
                return token;
              });
            };

            return <p key={pIdx} className="text-gray-200">{formatInline(trimmed)}</p>;
          })}
        </div>
      );
    });
  };

  return (
    <div
      data-msg-id={message.id}
      className={`group flex flex-col gap-1 w-full animate-in fade-in slide-in-from-bottom-2 duration-200 select-text ${
        isUser ? "items-end" : "items-start"
      }`}
    >
      {/* Pinned Badge */}
      {message.pinned && (
        <div className="flex items-center gap-1 text-[10px] text-amber-400 font-bold bg-amber-950/60 border border-amber-500/50 px-2 py-0.5 rounded-full mb-0.5">
          <Pin className="w-3 h-3" />
          <span>Pinned Concept</span>
        </div>
      )}

      {/* Message Box */}
      <div
        className={`max-w-[92%] sm:max-w-[85%] rounded-2xl text-xs sm:text-[13px] relative transition-all duration-200 backdrop-blur-xl shadow-lg overflow-hidden flex flex-col ${
          isUser
            ? "bg-gradient-to-br from-cyan-950/60 to-slate-900/80 border border-cyan-400/40 text-slate-100 shadow-[0_4px_25px_rgba(34,211,238,0.15)] rounded-br-sm"
            : "bg-slate-900/80 border border-white/10 text-slate-200 shadow-[0_4px_25px_rgba(0,0,0,0.3)] rounded-bl-sm"
        }`}
      >
        <div className="px-4 py-3 sm:px-5 sm:py-3.5">
          {/* Attached Images */}
          {message.images && message.images.length > 0 && (
            <div className="flex flex-wrap gap-2 mb-2.5">
              {message.images.map((img, idx) => (
                <div key={idx} className="rounded-xl overflow-hidden border border-white/10 bg-black max-w-[150px] max-h-[120px] shadow-sm">
                  <img src={`data:${img.mimeType};base64,${img.base64Data}`} alt={img.name} className="w-full h-full object-cover" />
                </div>
              ))}
            </div>
          )}

          {/* Text / Edit form */}
          {isEditing ? (
            <div className="space-y-2.5 w-full min-w-[280px]">
              <textarea
                value={editText}
                onChange={(e) => setEditText(e.target.value)}
                className="w-full bg-slate-950/90 border border-cyan-400/80 rounded-xl p-3 text-slate-200 font-mono text-xs outline-none min-h-[80px] resize-y shadow-inner"
                autoFocus
              />
              <div className="flex justify-end gap-2">
                <button
                  onClick={() => setIsEditing(false)}
                  className="px-3 py-1 rounded-full bg-white/5 border border-white/10 text-slate-300 hover:text-white text-[11px] font-mono tracking-wider uppercase"
                >
                  Cancel
                </button>
                <button
                  onClick={handleSaveEdit}
                  className="px-3 py-1 rounded-full bg-cyan-400 text-slate-950 font-bold hover:bg-cyan-300 text-[11px] font-mono tracking-wider uppercase shadow-[0_0_15px_rgba(34,211,238,0.4)]"
                >
                  Save Changes
                </button>
              </div>
            </div>
          ) : (
            <div className="font-sans break-words leading-relaxed">{isUser ? <div className="whitespace-pre-wrap">{message.content}</div> : renderFormattedContent(message.content)}</div>
          )}
        </div>

        {/* Sleek Semi-Transparent Docked Action Bar & Metadata Inside Message Box */}
        <div className="flex items-center justify-between gap-2 px-3 py-1.5 bg-slate-950/70 border-t border-white/10 text-[10px] font-mono text-slate-400 flex-wrap backdrop-blur-md opacity-90 hover:opacity-100 transition-opacity">
          {/* Metadata */}
          {message.meta ? (
            <div className="flex items-center gap-2.5 uppercase tracking-wider font-semibold">
              <span className="text-cyan-400">{message.meta.tokens} tok</span>
              <span className="text-indigo-400">${message.meta.cost.toFixed(5)}</span>
              <span className="text-slate-300">{message.meta.latency} ms</span>
            </div>
          ) : (
            <span className="text-[9px] text-slate-500 uppercase tracking-widest">{isUser ? "USER COGNITION" : "NEURAL CORE RESPONSE"}</span>
          )}

          {/* Action Buttons */}
          <div className="flex items-center gap-1 sm:gap-1.5 ml-auto flex-wrap justify-end">
            {/* Copy */}
            <button
              onClick={handleCopy}
              className="flex items-center gap-1 px-2 py-0.5 rounded-md border border-white/10 bg-white/5 text-slate-400 hover:text-cyan-400 hover:border-cyan-400/50 transition-colors uppercase tracking-wider font-mono text-[9px]"
              title="Copy text"
            >
              {copied ? <Check className="w-3 h-3 text-emerald-400" /> : <Copy className="w-3 h-3" />}
              <span>{copied ? "Copied" : "Copy"}</span>
            </button>

            {/* Speak */}
            <button
              onClick={() => onSpeak(message.content)}
              className={`flex items-center gap-1 px-2 py-0.5 rounded-md border transition-colors uppercase tracking-wider font-mono text-[9px] ${
                isSpeaking
                  ? "bg-cyan-500/20 border-cyan-400 text-cyan-300 shadow-[0_0_10px_rgba(34,211,238,0.3)]"
                  : "border-white/10 bg-white/5 text-slate-400 hover:text-cyan-400 hover:border-cyan-400/50"
              }`}
              title="Speak message with TTS"
            >
              {isSpeaking ? <VolumeX className="w-3 h-3" /> : <Volume2 className="w-3 h-3" />}
              <span>{isSpeaking ? "Stop" : "Speak"}</span>
            </button>

            {/* Pin */}
            <button
              onClick={() => onTogglePin(message.id)}
              className={`flex items-center gap-1 px-2 py-0.5 rounded-md border transition-colors uppercase tracking-wider font-mono text-[9px] ${
                message.pinned
                  ? "bg-amber-500/20 border-amber-400 text-amber-300 font-bold shadow-[0_0_10px_rgba(251,191,36,0.3)]"
                  : "border-white/10 bg-white/5 text-slate-400 hover:text-cyan-400 hover:border-cyan-400/50"
              }`}
              title="Pin concept to neural memory"
            >
              <Pin className="w-3 h-3" />
              <span>{message.pinned ? "Pinned" : "Pin"}</span>
            </button>

            {/* AI only actions */}
            {!isUser && (
              <>
                <button
                  onClick={() => onRegenerate(message.id)}
                  className="flex items-center gap-1 px-2 py-0.5 rounded-md border border-white/10 bg-white/5 text-slate-400 hover:text-cyan-400 hover:border-cyan-400/50 transition-colors uppercase tracking-wider font-mono text-[9px]"
                  title="Regenerate response"
                >
                  <RotateCcw className="w-3 h-3" />
                  <span>Regenerate</span>
                </button>

                <button
                  onClick={() => onContinue(message.id)}
                  className="flex items-center gap-1 px-2 py-0.5 rounded-md border border-white/10 bg-white/5 text-slate-400 hover:text-cyan-400 hover:border-cyan-400/50 transition-colors uppercase tracking-wider font-mono text-[9px]"
                  title="Continue generating from here"
                >
                  <ArrowRight className="w-3 h-3" />
                  <span>Continue</span>
                </button>

                <button
                  onClick={() => onFeedback(message.id, "up")}
                  className={`p-1 rounded-md border transition-colors ${
                    message.feedback === "up"
                      ? "bg-emerald-500/20 border-emerald-400 text-emerald-300 shadow-[0_0_8px_rgba(52,211,153,0.3)]"
                      : "border-white/10 bg-white/5 text-slate-400 hover:text-cyan-400 hover:border-cyan-400/50"
                  }`}
                  title="Helpful response"
                >
                  <ThumbsUp className="w-3 h-3" />
                </button>

                <button
                  onClick={() => onFeedback(message.id, "down")}
                  className={`p-1 rounded-md border transition-colors ${
                    message.feedback === "down"
                      ? "bg-rose-500/20 border-rose-400 text-rose-300 shadow-[0_0_8px_rgba(244,63,94,0.3)]"
                      : "border-white/10 bg-white/5 text-slate-400 hover:text-cyan-400 hover:border-cyan-400/50"
                  }`}
                  title="Unhelpful response"
                >
                  <ThumbsDown className="w-3 h-3" />
                </button>
              </>
            )}

            {/* User edit */}
            {isUser && !isEditing && (
              <button
                onClick={() => setIsEditing(true)}
                className="flex items-center gap-1 px-2 py-0.5 rounded-md border border-white/10 bg-white/5 text-slate-400 hover:text-cyan-400 hover:border-cyan-400/50 transition-colors uppercase tracking-wider font-mono text-[9px]"
                title="Edit message"
              >
                <Edit3 className="w-3 h-3" />
                <span>Edit</span>
              </button>
            )}

            {/* Delete */}
            <button
              onClick={() => onDelete(message.id)}
              className="p-1 rounded-md border border-white/10 bg-white/5 text-slate-400 hover:text-rose-400 hover:border-rose-500/50 transition-colors"
              title="Delete message"
            >
              <Trash2 className="w-3 h-3" />
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useEffect, useRef } from "react";
import { Message } from "../types";
import { MessageItem } from "./MessageItem";
import { Pin, X, ArrowDown, ArrowRight, Search, Radio, Activity } from "lucide-react";

interface MessageListProps {
  messages: Message[];
  onCopyText: (text: string) => void;
  onSpeak: (text: string) => void;
  onTogglePin: (id: string) => void;
  onRegenerate: (id: string) => void;
  onContinue: (id: string) => void;
  onFeedback: (id: string, type: "up" | "down") => void;
  onEdit: (id: string, newText: string) => void;
  onDelete: (id: string) => void;
  onRunCode?: (code: string) => void;
  onOpenFrontEnd?: (code: string, lang: string) => void;
  speakingMsgId: string | null;
  isStreaming: boolean;
  streamingText: string;
  pinnedMessages: Message[];
  searchActive: boolean;
  searchQuery: string;
  onSearchSelect: (id: string) => void;
  onCloseSearch: () => void;
}

export const MessageList: React.FC<MessageListProps> = ({
  messages,
  onCopyText,
  onSpeak,
  onTogglePin,
  onRegenerate,
  onContinue,
  onFeedback,
  onEdit,
  onDelete,
  onRunCode,
  onOpenFrontEnd,
  speakingMsgId,
  isStreaming,
  streamingText,
  pinnedMessages,
  searchActive,
  searchQuery,
  onSearchSelect,
  onCloseSearch,
}) => {
  const bottomRef = useRef<HTMLDivElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [showScrollBtn, setShowScrollBtn] = React.useState(false);

  const scrollToBottom = (smooth = true) => {
    bottomRef.current?.scrollIntoView({ behavior: smooth ? "smooth" : "auto" });
  };

  useEffect(() => {
    scrollToBottom(false);
  }, [messages.length, isStreaming]);

  const handleScroll = () => {
    if (!containerRef.current) return;
    const { scrollTop, scrollHeight, clientHeight } = containerRef.current;
    const isNearBottom = scrollHeight - scrollTop - clientHeight < 100;
    setShowScrollBtn(!isNearBottom);
  };

  // Filter messages for search
  const searchResults = React.useMemo(() => {
    if (!searchActive || !searchQuery.trim()) return [];
    const q = searchQuery.toLowerCase();
    return messages.filter(m => m.content.toLowerCase().includes(q));
  }, [searchActive, searchQuery, messages]);

  return (
    <div className="flex-1 flex flex-col min-h-0 relative bg-gradient-to-b from-[#0a0c10]/40 to-[#0e1218]/40 overflow-hidden">
      {/* Pinned Messages Bar */}
      {pinnedMessages.length > 0 && (
        <div className="px-3 py-1.5 bg-amber-950/20 border-b border-amber-500/30 text-xs font-mono select-none max-h-28 overflow-y-auto shrink-0">
          <div className="flex items-center gap-1.5 text-amber-400 font-bold mb-1 text-[10px] uppercase tracking-wider">
            <Pin className="w-3 h-3" />
            <span>Pinned Neural Concepts ({pinnedMessages.length})</span>
          </div>
          <div className="space-y-1">
            {pinnedMessages.map(pm => (
              <div key={pm.id} className="flex items-center justify-between gap-2 bg-black/40 px-2 py-1 rounded border border-amber-500/20 text-gray-300">
                <span className="truncate max-w-[85%] text-[11px]">{pm.content}</span>
                <button
                  onClick={() => onTogglePin(pm.id)}
                  className="text-gray-500 hover:text-red-400 p-0.5"
                  title="Unpin concept"
                >
                  <X className="w-3 h-3" />
                </button>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Search Results Overlay */}
      {searchActive && (
        <div className="absolute inset-0 bg-[#0d1117]/98 z-30 flex flex-col p-4 font-mono select-none animate-in fade-in duration-150">
          <div className="flex items-center justify-between pb-2 mb-3 border-b border-gray-800 text-gray-200">
            <div className="flex items-center gap-2 font-bold text-cyan-400 text-xs uppercase tracking-wider">
              <Search className="w-4 h-4" />
              <span>Search Results for &quot;{searchQuery}&quot; ({searchResults.length})</span>
            </div>
            <button
              onClick={onCloseSearch}
              className="p-1 rounded bg-gray-800 text-gray-400 hover:text-white"
            >
              <X className="w-4 h-4" />
            </button>
          </div>
          <div className="flex-1 overflow-y-auto space-y-2 pr-1 scrollbar-thin">
            {searchResults.length === 0 ? (
              <div className="text-gray-500 italic text-center py-8">No matching messages found in this tab.</div>
            ) : (
              searchResults.map((res, i) => (
                <div
                  key={res.id}
                  onClick={() => {
                    onSearchSelect(res.id);
                    onCloseSearch();
                  }}
                  className="p-2.5 rounded-lg border border-gray-800 bg-[#141820] hover:border-cyan-500 cursor-pointer transition-all text-xs"
                >
                  <div className="flex items-center justify-between text-[10px] text-gray-500 mb-1 font-bold uppercase">
                    <span>{res.role} · Match #{i + 1}</span>
                    <span>{new Date(res.timestamp).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })}</span>
                  </div>
                  <div className="text-gray-300 line-clamp-2 font-sans">{res.content}</div>
                </div>
              ))
            )}
          </div>
        </div>
      )}

      {/* Messages Scroll Area */}
      <div
        ref={containerRef}
        onScroll={handleScroll}
        className="flex-1 overflow-y-auto p-4 space-y-4 scroll-smooth scrollbar-thin"
      >
        {messages.length === 0 ? (
          <div className="h-full flex flex-col items-center justify-center text-center p-6 text-gray-500 font-mono select-none">
            <Activity className="w-10 h-10 text-cyan-500/40 animate-pulse mb-3" />
            <h3 className="text-sm font-bold text-gray-300 tracking-wider uppercase mb-1">Cortex Synapse Ready</h3>
            <p className="max-w-md text-xs text-gray-500 leading-relaxed">
              Initiate a neural stimulus below. Ask SenPai a question, attach code or documents, or trigger Autonomous Mission Mode.
            </p>
          </div>
        ) : (
          messages.map((msg) => (
            <MessageItem
              key={msg.id}
              message={msg}
              onCopyText={onCopyText}
              onSpeak={onSpeak}
              onTogglePin={onTogglePin}
              onRegenerate={onRegenerate}
              onContinue={onContinue}
              onFeedback={onFeedback}
              onEdit={onEdit}
              onDelete={onDelete}
              onRunCode={onRunCode}
              onOpenFrontEnd={onOpenFrontEnd}
              isSpeaking={speakingMsgId === msg.id}
            />
          ))
        )}

        {/* Streaming / Typing Indicator */}
        {isStreaming && (
          <div className="flex flex-col gap-1 items-start max-w-[85%] animate-in fade-in duration-200">
            <div className="flex items-center gap-2 px-3 py-1.5 rounded-t-xl bg-[#11131a] border border-purple-500/20 text-purple-400 font-mono text-[10px] font-bold uppercase tracking-wider">
              <Radio className="w-3 h-3 animate-spin text-cyan-400" />
              <span>SENPAI NEURAL PROCESSING...</span>
            </div>
            <div className="px-3.5 py-2.5 rounded-xl rounded-tl-none bg-[#11131a] border border-purple-500/20 text-gray-100 shadow-md text-xs sm:text-[13px] font-sans whitespace-pre-wrap w-full">
              {streamingText || <span className="text-gray-500 italic font-mono">Receiving synaptic token stream...</span>}
              <span className="inline-block ml-1 w-2 h-4 bg-cyan-400 animate-pulse align-middle" />
            </div>
          </div>
        )}

        <div ref={bottomRef} />
      </div>

      {/* Floating Scroll to Bottom Button */}
      {showScrollBtn && (
        <button
          onClick={() => scrollToBottom(true)}
          className="absolute bottom-4 right-4 z-20 w-8 h-8 rounded-full bg-[#161b22] border border-gray-700 text-gray-300 hover:text-white hover:border-cyan-400 flex items-center justify-center shadow-lg transition-all animate-bounce"
          title="Scroll to bottom"
        >
          <ArrowRight className="w-4 h-4 rotate-90" />
        </button>
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from "react";
import { Search, MessageSquare, Folder, Terminal, ArrowRight, CornerDownLeft, Sparkles, X } from "lucide-react";
import { ConversationTab, SavedConversation, Message } from "../types";

interface MiniSearchOverlayProps {
  isOpen: boolean;
  onClose: () => void;
  activeTab: ConversationTab | null;
  savedConversations: SavedConversation[];
  onSelectMessage: (msgId: string) => void;
  onSelectConversation: (convId: string) => void;
  onOpenAdmin: () => void;
  onOpenMission: () => void;
}

interface SearchResult {
  id: string;
  type: "message" | "conversation" | "action";
  title: string;
  subtitle: string;
  meta?: string;
  action: () => void;
}

export const MiniSearchOverlay: React.FC<MiniSearchOverlayProps> = ({
  isOpen,
  onClose,
  activeTab,
  savedConversations,
  onSelectMessage,
  onSelectConversation,
  onOpenAdmin,
  onOpenMission,
}) => {
  const [query, setQuery] = useState("");
  const [selectedIndex, setSelectedIndex] = useState(0);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (isOpen) {
      setQuery("");
      setSelectedIndex(0);
      setTimeout(() => inputRef.current?.focus(), 50);
    }
  }, [isOpen]);

  const results: SearchResult[] = React.useMemo(() => {
    const q = query.trim().toLowerCase();
    const list: SearchResult[] = [];

    // Quick system actions if empty or matches
    const actions = [
      { id: "act-admin", name: "Open Admin Portal & News Manager", desc: "Configure AI OS, News (Markdown), SKILL.md & Passwords", act: () => { onClose(); onOpenAdmin(); } },
      { id: "act-mission", name: "Launch Autonomous Mission Mode", desc: "3D cognitive task decomposition & execution", act: () => { onClose(); onOpenMission(); } },
    ];

    if (!q) {
      actions.forEach((a) => {
        list.push({
          id: a.id,
          type: "action",
          title: a.name,
          subtitle: a.desc,
          meta: "COMMAND",
          action: a.act,
        });
      });
    } else {
      actions.forEach((a) => {
        if (a.name.toLowerCase().includes(q) || a.desc.toLowerCase().includes(q)) {
          list.push({
            id: a.id,
            type: "action",
            title: a.name,
            subtitle: a.desc,
            meta: "COMMAND",
            action: a.act,
          });
        }
      });
    }

    // Search active tab messages
    if (activeTab) {
      activeTab.messages.forEach((m) => {
        if (!q || m.content.toLowerCase().includes(q)) {
          const preview = m.content.replace(/\n/g, " ").slice(0, 85) + (m.content.length > 85 ? "..." : "");
          list.push({
            id: `msg-${m.id}`,
            type: "message",
            title: m.role === "user" ? "USER PROMPT" : "SENPAI RESPONSE",
            subtitle: preview,
            meta: new Date(m.timestamp).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }),
            action: () => {
              onClose();
              onSelectMessage(m.id);
            },
          });
        }
      });
    }

    // Search archives
    savedConversations.forEach((c) => {
      if (!q || c.title.toLowerCase().includes(q) || c.messages.some((m) => m.content.toLowerCase().includes(q))) {
        list.push({
          id: `conv-${c.id}`,
          type: "conversation",
          title: c.title || "Untitled Conversation",
          subtitle: `Saved archive with ${c.messages.length} messages (${c.date})`,
          meta: "ARCHIVE",
          action: () => {
            onClose();
            onSelectConversation(c.id);
          },
        });
      }
    });

    return list.slice(0, 12);
  }, [query, activeTab, savedConversations, onClose, onOpenAdmin, onOpenMission, onSelectMessage, onSelectConversation]);

  useEffect(() => {
    if (selectedIndex >= results.length && results.length > 0) {
      setSelectedIndex(results.length - 1);
    }
  }, [results.length, selectedIndex]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (!isOpen) return;
      if (e.key === "Escape") {
        onClose();
      } else if (e.key === "ArrowDown") {
        e.preventDefault();
        setSelectedIndex((prev) => (prev + 1) % (results.length || 1));
      } else if (e.key === "ArrowUp") {
        e.preventDefault();
        setSelectedIndex((prev) => (prev - 1 + (results.length || 1)) % (results.length || 1));
      } else if (e.key === "Enter" && results[selectedIndex]) {
        e.preventDefault();
        results[selectedIndex].action();
      }
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [isOpen, results, selectedIndex, onClose]);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-start justify-center pt-[15vh] bg-slate-950/80 backdrop-blur-md p-4 animate-fadeIn">
      <div 
        className="w-full max-w-2xl bg-slate-900 border border-cyan-500/40 rounded-2xl shadow-[0_0_50px_rgba(6,182,212,0.25)] overflow-hidden flex flex-col font-mono text-xs text-slate-200"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Search Header */}
        <div className="flex items-center gap-3 px-4 py-3.5 border-b border-cyan-500/20 bg-slate-950/60">
          <Search className="w-4 h-4 text-cyan-400 shrink-0 animate-pulse" />
          <input
            ref={inputRef}
            type="text"
            value={query}
            onChange={(e) => {
              setQuery(e.target.value);
              setSelectedIndex(0);
            }}
            placeholder="Type to search active messages, archived chats, or commands..."
            className="flex-1 bg-transparent border-none outline-none text-slate-100 placeholder-slate-500 text-sm font-sans"
          />
          <div className="flex items-center gap-1.5 shrink-0">
            <span className="px-1.5 py-0.5 rounded bg-cyan-500/10 border border-cyan-500/30 text-[10px] text-cyan-300 font-mono font-bold">ESC</span>
            <button
              onClick={onClose}
              className="p-1 hover:bg-white/10 rounded-lg text-slate-400 hover:text-white transition-colors"
            >
              <X className="w-4 h-4" />
            </button>
          </div>
        </div>

        {/* Results List */}
        <div className="max-h-[60vh] overflow-y-auto divide-y divide-white/5 p-2">
          {results.length === 0 ? (
            <div className="p-8 text-center text-slate-500 italic">
              No neural records matching "{query}" found in current synapse memory.
            </div>
          ) : (
            results.map((item, idx) => {
              const isSelected = idx === selectedIndex;
              return (
                <div
                  key={item.id}
                  onClick={() => item.action()}
                  onMouseEnter={() => setSelectedIndex(idx)}
                  className={`flex items-center justify-between gap-3 p-3 rounded-xl cursor-pointer transition-all ${
                    isSelected
                      ? "bg-gradient-to-r from-cyan-500/20 to-blue-500/10 border border-cyan-500/40 text-white shadow-[0_0_15px_rgba(6,182,212,0.15)]"
                      : "hover:bg-white/5 text-slate-300"
                  }`}
                >
                  <div className="flex items-center gap-3 min-w-0 flex-1">
                    <div className={`p-2 rounded-lg shrink-0 ${
                      item.type === "action" ? "bg-amber-500/15 text-amber-400 border border-amber-500/30" :
                      item.type === "conversation" ? "bg-purple-500/15 text-purple-400 border border-purple-500/30" :
                      "bg-cyan-500/15 text-cyan-300 border border-cyan-500/30"
                    }`}>
                      {item.type === "action" ? <Terminal className="w-4 h-4" /> :
                       item.type === "conversation" ? <Folder className="w-4 h-4" /> :
                       <MessageSquare className="w-4 h-4" />}
                    </div>
                    <div className="min-w-0 flex-1">
                      <div className="flex items-center gap-2">
                        <span className="font-bold text-slate-100 text-xs truncate">{item.title}</span>
                        {item.meta && (
                          <span className="px-1.5 py-0.2 rounded bg-white/5 text-[9px] text-slate-400 uppercase tracking-wider">{item.meta}</span>
                        )}
                      </div>
                      <p className="text-slate-400 text-[11px] truncate mt-0.5 font-sans">{item.subtitle}</p>
                    </div>
                  </div>

                  <div className="flex items-center gap-1 text-slate-500 shrink-0">
                    {isSelected && <CornerDownLeft className="w-3.5 h-3.5 text-cyan-400 animate-bounce" />}
                  </div>
                </div>
              );
            })
          )}
        </div>

        {/* Search Footer */}
        <div className="px-4 py-2 border-t border-white/5 bg-slate-950/80 flex items-center justify-between text-[10px] text-slate-400">
          <div className="flex items-center gap-3">
            <span><kbd className="px-1 py-0.5 bg-white/10 rounded text-slate-300">↑↓</kbd> to navigate</span>
            <span><kbd className="px-1 py-0.5 bg-white/10 rounded text-slate-300">ENTER</kbd> to jump</span>
          </div>
          <div className="flex items-center gap-1.5 text-cyan-400">
            <Sparkles className="w-3 h-3 animate-pulse" />
            <span>NEURAL SEARCH INDEX v4.0</span>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from "react";
import { MissionTask } from "../types";
import { Target, X, Play, CheckCircle, Clock, AlertCircle, Loader2 } from "lucide-react";

interface MissionModalProps {
