    skillsList.forEach((s) => {
      parseSkillMdAsync(s.content, s.name, s.description, s.category, s.usageCount).catch(() => {});
    });
  }, [skillsList]);

  // Set first skill selected by default
  useEffect(() => {
    if (skillsList.length > 0 && !selectedSkill) {
      setSelectedSkill(skillsList[0]);
