let audioCtx: AudioContext | null = null;

function getAudioContext(): AudioContext | null {
  if (typeof window === "undefined") return null;
  if (!audioCtx) {
    const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
    if (AudioContextClass) {
      audioCtx = new AudioContextClass();
    }
  }
  if (audioCtx && audioCtx.state === "suspended") {
    audioCtx.resume().catch(() => {});
  }
  return audioCtx;
}

class AudioController {
  private muted: boolean = false;
  private volume: number = 0.8;

  constructor() {
    if (typeof window !== "undefined") {
      const savedMuted = localStorage.getItem("neuro_audio_muted");
      const savedVol = localStorage.getItem("neuro_audio_volume");
      if (savedMuted !== null) this.muted = savedMuted === "true";
      if (savedVol !== null) {
        const parsed = parseFloat(savedVol);
        if (!isNaN(parsed)) this.volume = Math.max(0, Math.min(1, parsed));
      }
    }
  }

  getMuted(): boolean {
    return this.muted;
  }

  setMuted(muted: boolean): void {
    this.muted = muted;
    if (typeof window !== "undefined") {
      localStorage.setItem("neuro_audio_muted", String(muted));
    }
  }

  toggleMute(): boolean {
    this.setMuted(!this.muted);
    return this.muted;
  }

  getVolume(): number {
    return this.volume;
  }

  setVolume(vol: number): void {
    this.volume = Math.max(0, Math.min(1, vol));
    if (typeof window !== "undefined") {
      localStorage.setItem("neuro_audio_volume", String(this.volume));
    }
  }

  private canPlay(enabled: boolean): boolean {
    return enabled && !this.muted && this.volume > 0;
  }

  // Trigger 'Connection Chime' for active nodes
  playConnectionChime(enabled: boolean = true) {
    if (!this.canPlay(enabled)) return;
    const ctx = getAudioContext();
    if (!ctx) return;
    try {
      const now = ctx.currentTime;
      const notes = [523.25, 659.25, 783.99, 1046.50]; // C5, E5, G5, C6 chord
      notes.forEach((freq, idx) => {
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.type = "sine";
        osc.frequency.setValueAtTime(freq, now + idx * 0.06);
        gain.gain.setValueAtTime((0.07 * this.volume), now + idx * 0.06);
        gain.gain.exponentialRampToValueAtTime(0.001, now + idx * 0.06 + 0.4);
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.start(now + idx * 0.06);
        osc.stop(now + idx * 0.06 + 0.4);
      });
    } catch (_) {}
  }

  // Trigger 'Error Pulse' for 429/rate-limit alerts
  playErrorPulse(enabled: boolean = true) {
    if (!this.canPlay(enabled)) return;
    const ctx = getAudioContext();
    if (!ctx) return;
    try {
      const now = ctx.currentTime;
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = "sawtooth";
      osc.frequency.setValueAtTime(150, now);
      osc.frequency.setValueAtTime(110, now + 0.12);
      osc.frequency.setValueAtTime(90, now + 0.24);
      gain.gain.setValueAtTime((0.12 * this.volume), now);
      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.35);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(now);
      osc.stop(now + 0.35);
    } catch (_) {}
  }

  // Trigger 'Interaction Click' for node toggles
  playInteractionClick(enabled: boolean = true) {
    if (!this.canPlay(enabled)) return;
    const ctx = getAudioContext();
    if (!ctx) return;
    try {
      const now = ctx.currentTime;
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = "sine";
      osc.frequency.setValueAtTime(1200, now);
      osc.frequency.exponentialRampToValueAtTime(600, now + 0.04);
      gain.gain.setValueAtTime((0.05 * this.volume), now);
      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.05);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(now);
      osc.stop(now + 0.05);
    } catch (_) {}
  }

  // Trigger 'Node Pulse' for real-time health data
  playNodePulse(enabled: boolean = true) {
    if (!this.canPlay(enabled)) return;
    const ctx = getAudioContext();
    if (!ctx) return;
    try {
      const now = ctx.currentTime;
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = "triangle";
      osc.frequency.setValueAtTime(330, now);
      osc.frequency.exponentialRampToValueAtTime(165, now + 0.2);
      gain.gain.setValueAtTime((0.04 * this.volume), now);
      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.25);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(now);
      osc.stop(now + 0.25);
    } catch (_) {}
  }
}

export const AudioEngine = new AudioController();

export function playSpawnSound(enabled: boolean = true) {
  if (!AudioEngine["canPlay"](enabled)) return;
  const ctx = getAudioContext();
  if (!ctx) return;
  try {
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = "sine";
    const now = ctx.currentTime;
    osc.frequency.setValueAtTime(440, now);
    osc.frequency.exponentialRampToValueAtTime(880, now + 0.15);
    gain.gain.setValueAtTime(0.08 * AudioEngine.getVolume(), now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.2);
    osc.connect(gain);
    gain.connect(ctx.destination);
    osc.start(now);
    osc.stop(now + 0.2);
  } catch (_) {}
}

export function playPulseSound(enabled: boolean = true) {
  if (!AudioEngine["canPlay"](enabled)) return;
  const ctx = getAudioContext();
  if (!ctx) return;
  try {
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = "triangle";
    const now = ctx.currentTime;
    osc.frequency.setValueAtTime(220, now);
    osc.frequency.exponentialRampToValueAtTime(110, now + 0.3);
    gain.gain.setValueAtTime(0.05 * AudioEngine.getVolume(), now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.35);
    osc.connect(gain);
    gain.connect(ctx.destination);
    osc.start(now);
    osc.stop(now + 0.35);
  } catch (_) {}
}

export function playClickSound(enabled: boolean = true) {
  AudioEngine.playInteractionClick(enabled);
}

export function playErrorSound(enabled: boolean = true) {
  AudioEngine.playErrorPulse(enabled);
}

export function playMissionCompleteSound(enabled: boolean = true) {
  AudioEngine.playConnectionChime(enabled);
}

const SENPAI_IDB_NAME = "senpai_secure_store_v2";
const SENPAI_IDB_KEY_ID = "apiKeyEncKey";
let _senpaiCryptoKeyPromise: Promise<CryptoKey> | null = null;

function openSenpaiIDB(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const req = indexedDB.open(SENPAI_IDB_NAME, 1);
    req.onupgradeneeded = () => {
      req.result.createObjectStore("keys");
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

async function getOrCreateCryptoKey(): Promise<CryptoKey> {
  if (_senpaiCryptoKeyPromise) return _senpaiCryptoKeyPromise;
  _senpaiCryptoKeyPromise = (async () => {
    try {
      const db = await openSenpaiIDB();
      const existing = await new Promise<CryptoKey | null>((resolve, reject) => {
        const tx = db.transaction("keys", "readonly");
        const req = tx.objectStore("keys").get(SENPAI_IDB_KEY_ID);
        req.onsuccess = () => resolve(req.result || null);
        req.onerror = () => reject(req.error);
      });
      if (existing) return existing;

      // generate non-extractable AES-GCM key
      const key = await crypto.subtle.generateKey(
        { name: "AES-GCM", length: 256 },
        false,
        ["encrypt", "decrypt"]
      );

      await new Promise<void>((resolve, reject) => {
        const tx = db.transaction("keys", "readwrite");
        tx.objectStore("keys").put(key, SENPAI_IDB_KEY_ID);
        tx.oncomplete = () => resolve();
        tx.onerror = () => reject(tx.error);
      });
      return key;
    } catch (err) {
      console.warn("IDB/Crypto not available, generating ephemeral key for session:", err);
      return crypto.subtle.generateKey(
        { name: "AES-GCM", length: 256 },
        false,
        ["encrypt", "decrypt"]
      );
    }
  })();
  return _senpaiCryptoKeyPromise;
}

export async function encryptText(text: string): Promise<string> {
  if (!text) return "";
  try {
    const key = await getOrCreateCryptoKey();
    const data = new TextEncoder().encode(text);
    const iv = crypto.getRandomValues(new Uint8Array(12));
    const encrypted = await crypto.subtle.encrypt({ name: "AES-GCM", iv }, key, data);
    const combined = new Uint8Array(iv.length + encrypted.byteLength);
    combined.set(iv, 0);
    combined.set(new Uint8Array(encrypted), iv.length);
    return btoa(String.fromCharCode(...combined));
  } catch (err) {
    console.error("encryptText failed, using base64 fallback:", err);
    return btoa(encodeURIComponent(text));
  }
}

export async function decryptText(enc: string): Promise<string> {
  if (!enc) return "";
  try {
    const key = await getOrCreateCryptoKey();
    const combined = Uint8Array.from(atob(enc), c => c.charCodeAt(0));
    const iv = combined.slice(0, 12);
    const ciphertext = combined.slice(12);
    const decrypted = await crypto.subtle.decrypt({ name: "AES-GCM", iv }, key, ciphertext);
    return new TextDecoder().decode(decrypted);
  } catch (err) {
    try {
      return decodeURIComponent(atob(enc));
    } catch (_) {
      return "";
    }
  }
}
